package core

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"unicode/utf8"
)

// headlineCorpus mirrors spec/corpus/headline.json. The corpus is generated by
// tests/gen-corpus.ts (EKB-009) from tests/capture.test.ts and is the sole
// judge for the Go implementation.
type headlineCorpus struct {
	Cases []headlineCase `json:"cases"`
}

type headlineCase struct {
	CaseID   string `json:"case_id"`
	Input    string `json:"input"`
	Expected struct {
		Line string `json:"line"`
		Code string `json:"code"`
	} `json:"expected"`
}

func loadHeadlineCorpus(t *testing.T) headlineCorpus {
	t.Helper()
	path := filepath.Join("..", "..", "spec", "corpus", "headline.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	var corpus headlineCorpus
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}
	if len(corpus.Cases) == 0 {
		t.Fatal("corpus has no cases")
	}
	return corpus
}

func TestHeadlineCorpus(t *testing.T) {
	corpus := loadHeadlineCorpus(t)
	for _, testCase := range corpus.Cases {
		t.Run(testCase.CaseID, func(t *testing.T) {
			got := ExtractHeadline(testCase.Input)
			if got.Line != testCase.Expected.Line {
				t.Errorf("line: got %q, want %q", got.Line, testCase.Expected.Line)
			}
			if got.Code != testCase.Expected.Code {
				t.Errorf("code: got %q, want %q", got.Code, testCase.Expected.Code)
			}
			// Determinism: the same input must always yield the same headline.
			if again := ExtractHeadline(testCase.Input); again != got {
				t.Errorf("second call differs: %+v vs %+v", again, got)
			}
		})
	}
}

// TestHeadlineBoundaries covers inputs the corpus does not: ANSI-only text,
// a lone carriage return, a traceback marker with no exception line, and a
// long line whose cap boundary is whitespace. These assert the declared
// boundary behaviour only; they are not corpus cases.
func TestHeadlineBoundaries(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  Headline
	}{
		{"ansi only", "\x1b[31m\x1b[0m", Headline{}},
		{"carriage returns", "\r\r", Headline{}},
		{"traceback without exception", tracebackMarker + "\n  File \"x.py\"", Headline{Line: "File \"x.py\""}},
		{"empty", "", Headline{}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if got := ExtractHeadline(test.input); got != test.want {
				t.Errorf("got %+v, want %+v", got, test.want)
			}
		})
	}

	// The cap keeps HeadlineMaxChars runes, the last one an ellipsis, and never
	// leaves a trailing space before the ellipsis. The corpus only covers a
	// line that ends in a non-space character.
	long := strings.Repeat("y", 300)
	capped := capHeadline(long)
	if utf8.RuneCountInString(capped) != HeadlineMaxChars {
		t.Errorf("capped length: got %d, want %d", utf8.RuneCountInString(capped), HeadlineMaxChars)
	}
	if !strings.HasSuffix(capped, "…") {
		t.Errorf("capped text does not end with an ellipsis: %q", capped)
	}
	// Trimming the rune before the ellipsis stays within the cap.
	spaced := strings.Repeat("y", HeadlineMaxChars-2) + "  " + "tail"
	trimmed := capHeadline(spaced)
	if utf8.RuneCountInString(trimmed) > HeadlineMaxChars {
		t.Errorf("trimmed length: got %d, want <= %d", utf8.RuneCountInString(trimmed), HeadlineMaxChars)
	}
	if strings.Contains(trimmed, " …") {
		t.Errorf("capped text leaves a space before the ellipsis: %q", trimmed)
	}
}
